import json
from fractions import Fraction as F
from pathlib import Path
base=Path(__file__).parents[1];d=json.loads((base/'results'/'rh_quarter_extremal_two_label_hall_factorization.json').read_text());P=list(map(lambda x:F(int(x['coefficient'])),d['comparable_positive_neighborhood']));D=list(map(lambda x:F(int(x['coefficient'])),d['normalized_demands']));lo=D[0]-P[0];hi=P[1]+P[2]-D[1];width=hi-lo;collective=sum(P)-sum(D);x=(lo+hi)/2;flows={'P0_to_D0':D[0]-x,'P1_to_D0':x,'P1_to_D1':P[1]-x,'P2_to_D1':D[1]-P[1]+x}
