result={'schema':'marici.strominger.rh_quarter_extremal_cover_allocation_interval.v1','status':'passed','admissible_interval':{'lower':q(lo),'upper':q(hi),'width':q(width)},'collective_slack':q(collective),'canonical_midpoint':q(x),'canonical_edge_flows':{k:q(v) for k,v in flows.items()},'unused_supplies':{'P0':q(P[0]-flows['P0_to_D0']),'P1':q(P[1]-flows['P1_to_D0']-flows['P1_to_D1']),'P2':q(P[2]-flows['P2_to_D1'])},'verdict':'The collective Hall slack is exactly the width of the feasible central-supply split interval; its midpoint gives a canonical exact interior flow.','checks':{'width_equals_collective_slack':width==collective,'strict_interior':lo<x<hi,'all_flows_nonnegative':all(v>=0 for v in flows.values()),'demands_exact':flows['P0_to_D0']+flows['P1_to_D0']==D[0] and flows['P1_to_D1']+flows['P2_to_D1']==D[1],'supplies_respected':flows['P0_to_D0']<=P[0] and flows['P1_to_D0']+flows['P1_to_D1']<=P[1] and flows['P2_to_D1']<=P[2]}}
(base/'results'/'rh_quarter_extremal_cover_allocation_interval.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
